/*__ESM_BODY_START__*/window.process={};import{j as jsxRuntimeExports,r as reactExports}from"./dashboard.jsdbx";import{i as insertStyle,N as NavHeader}from"./NavHeader.jsdbx";insertStyle('@charset "UTF-8";
/* --- Dark Store Dashboard — Dark Theme --- */
/* --- Dashboard Shell --- */
.ds-dashboard {
 min-height: 100vh;
 background: #0a0e14;
 color: #e2e8f0;
 font-family: -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI", sans-serif;
}

.ds-dashboard__content {
 padding: 24px;
 max-width: 1440px;
 margin: 0 auto;
}

/* --- Breadcrumb --- */
.ds-breadcrumb {
 display: flex;
 align-items: center;
 gap: 8px;
 margin-bottom: 16px;
 font-size: 13px;
}

.ds-breadcrumb__link {
 color: #3b82f6;
 text-decoration: none;
}

.ds-breadcrumb__link:hover {
 text-decoration: underline;
}

.ds-breadcrumb__sep {
 color: #475569;
}

.ds-breadcrumb__current {
 color: #94a3b8;
}

/* --- Store Header Card --- */
.ds-store-header {
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 padding: 24px;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 margin-bottom: 16px;
}

.ds-store-header__left {
 flex: 1;
}

.ds-store-header__title-row {
 display: flex;
 align-items: center;
 gap: 12px;
 margin-bottom: 6px;
}

.ds-store-header__name {
 font-size: 24px;
 font-weight: 700;
 color: #e2e8f0;
 margin: 0;
}

.ds-store-header__id-badge {
 font-size: 12px;
 font-weight: 600;
 color: #64748b;
 background: rgba(100, 116, 139, 0.12);
 border: 1px solid #1a2035;
 border-radius: 6px;
 padding: 3px 10px;
}

.ds-store-header__subtitle {
 font-size: 13px;
 color: #64748b;
 margin: 0 0 12px 0;
}

.ds-store-header__pills {
 display: flex;
 gap: 8px;
 flex-wrap: wrap;
}

.ds-store-header__pill {
 font-size: 11px;
 font-weight: 600;
 padding: 4px 10px;
 border-radius: 6px;
}

.ds-store-header__pill--red {
 color: #ef4444;
 background: rgba(239, 68, 68, 0.08);
 border: 1px solid rgba(239, 68, 68, 0.2);
}

.ds-store-header__pill--grey {
 color: #94a3b8;
 background: rgba(148, 163, 184, 0.08);
 border: 1px solid rgba(148, 163, 184, 0.15);
}

.ds-store-header__right {
 flex-shrink: 0;
}

.ds-store-header__live-pill {
 display: inline-flex;
 align-items: center;
 gap: 8px;
 font-size: 12px;
 color: #94a3b8;
 background: rgba(34, 197, 94, 0.06);
 border: 1px solid rgba(34, 197, 94, 0.2);
 border-radius: 20px;
 padding: 5px 14px;
}

.ds-store-header__live-dot {
 width: 7px;
 height: 7px;
 border-radius: 50%;
 background: #22c55e;
 animation: ds-pulse-glow 2s infinite;
}

@keyframes ds-pulse-glow {
 0%, 100% {
 opacity: 1;
 }
 50% {
 opacity: 0.4;
 }
}
/* --- PulseScore Breakdown --- */
.ds-pulse-breakdown {
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 padding: 24px;
 margin-bottom: 16px;
}

.ds-pulse-breakdown__text {
 margin-bottom: 14px;
}

.ds-pulse-breakdown__formula {
 font-size: 14px;
 color: #94a3b8;
}

.ds-pulse-breakdown__score {
 font-size: 28px;
 font-weight: 700;
 color: #ef4444;
 font-variant-numeric: tabular-nums;
}

.ds-pulse-breakdown__bar {
 display: flex;
 height: 24px;
 border-radius: 6px;
 overflow: hidden;
 gap: 2px;
 margin-bottom: 10px;
}

.ds-pulse-breakdown__segment {
 border-radius: 4px;
}

.ds-pulse-breakdown__segment--green {
 background: #22c55e;
}

.ds-pulse-breakdown__segment--red {
 background: #ef4444;
}

.ds-pulse-breakdown__labels {
 display: flex;
 gap: 24px;
 margin-bottom: 12px;
}

.ds-pulse-breakdown__label {
 font-size: 11px;
 font-weight: 600;
 color: #ef4444;
}

.ds-pulse-breakdown__caption {
 font-size: 12px;
 color: #64748b;
 font-style: italic;
 margin: 0;
 line-height: 1.5;
}

/* --- KPI Row --- */
.ds-kpi-row {
 display: grid;
 grid-template-columns: repeat(5, 1fr);
 gap: 16px;
 margin-bottom: 24px;
}

/* --- KPI Card --- */
.ds-kpi-card {
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 padding: 20px;
 display: flex;
 flex-direction: column;
}

.ds-kpi-card__label {
 font-size: 11px;
 font-weight: 600;
 color: #64748b;
 text-transform: uppercase;
 letter-spacing: 0.6px;
 margin-bottom: 10px;
}

.ds-kpi-card__value-row {
 display: flex;
 align-items: baseline;
 gap: 4px;
 margin-bottom: 10px;
}

.ds-kpi-card__value {
 font-size: 28px;
 font-weight: 700;
 color: #e2e8f0;
 font-variant-numeric: tabular-nums;
}

.ds-kpi-card__suffix {
 font-size: 14px;
 color: #64748b;
}

.ds-kpi-card__caption {
 font-size: 11px;
 color: #64748b;
 margin: 0;
 line-height: 1.5;
}

.ds-kpi-card__subcaption {
 font-size: 11px;
 color: #475569;
 margin: 4px 0 0 0;
 line-height: 1.5;
}

/* --- Generic Card --- */
.ds-card {
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 padding: 24px;
}

.ds-card__header {
 margin-bottom: 16px;
}

.ds-card__title {
 font-size: 15px;
 font-weight: 600;
 color: #e2e8f0;
 margin: 0 0 4px 0;
}

.ds-card__subtitle {
 font-size: 12px;
 color: #64748b;
 margin: 0;
}

/* --- Two-Column Layout --- */
.ds-dashboard__two-col {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: 16px;
 margin-bottom: 24px;
}

/* --- Three-Column Layout --- */
.ds-dashboard__three-col {
 display: grid;
 grid-template-columns: 1fr 1fr 1fr;
 gap: 16px;
 margin-bottom: 24px;
}

.ds-dashboard__complaints-col {
 display: flex;
 flex-direction: column;
 gap: 16px;
}

/* --- Bar Chart (Equipment) --- */
.ds-bar-chart {
 display: flex;
 gap: 8px;
 height: 180px;
 margin-bottom: 12px;
}

.ds-bar-chart__y-axis {
 display: flex;
 flex-direction: column;
 justify-content: space-between;
 padding: 0 4px 24px 0;
}

.ds-bar-chart__y-label {
 font-size: 10px;
 color: #475569;
 text-align: right;
 width: 20px;
}

.ds-bar-chart__body {
 display: flex;
 flex: 1;
 align-items: flex-end;
 gap: 4px;
 padding-bottom: 24px;
 border-bottom: 1px solid #1a2035;
}

.ds-bar-chart__col {
 flex: 1;
 display: flex;
 flex-direction: column;
 align-items: center;
 height: 100%;
}

.ds-bar-chart__bar-group {
 flex: 1;
 width: 100%;
 display: flex;
 align-items: flex-end;
 justify-content: center;
 gap: 2px;
}

.ds-bar-chart__bar {
 width: 40%;
 border-radius: 2px 2px 0 0;
 min-height: 2px;
}

.ds-bar-chart__bar--red {
 background: #ef4444;
}

.ds-bar-chart__bar--amber {
 background: #f59e0b;
}

.ds-bar-chart__x-label {
 font-size: 8px;
 color: #475569;
 margin-top: 6px;
 text-align: center;
 white-space: nowrap;
}

/* --- Chart Legend --- */
.ds-chart__legend {
 display: flex;
 gap: 20px;
 margin-top: 12px;
}

.ds-chart__legend-item {
 display: flex;
 align-items: center;
 gap: 6px;
 font-size: 11px;
 color: #64748b;
}

.ds-chart__legend-dot {
 width: 10px;
 height: 10px;
 border-radius: 50%;
}

.ds-chart__legend-dot--red {
 background: #ef4444;
}

.ds-chart__legend-dot--amber {
 background: #f59e0b;
}

.ds-chart__legend-dot--blue {
 background: #3b82f6;
}

/* --- Line Chart (SVG) --- */
.ds-line-chart-wrap {
 position: relative;
 margin-bottom: 8px;
}

.ds-line-chart-svg {
 display: block;
 width: 100%;
}

.ds-chart__axis-text {
 font-size: 10px;
 fill: #475569;
}

/* --- Tooltip --- */
.ds-tooltip {
 position: absolute;
 transform: translate(-50%, -100%);
 background: #1e293b;
 border: 1px solid #334155;
 border-radius: 6px;
 padding: 8px 12px;
 pointer-events: none;
 z-index: 10;
}

.ds-tooltip__date {
 font-size: 11px;
 font-weight: 600;
 color: #e2e8f0;
 margin-bottom: 4px;
}

.ds-tooltip__row {
 font-size: 11px;
 color: #94a3b8;
 line-height: 1.5;
}

/* --- List (Work Orders, Repairs, Complaints) --- */
.ds-list {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.ds-list__row {
 display: flex;
 align-items: center;
 justify-content: space-between;
 padding: 10px 12px;
 border-radius: 8px;
 transition: background 0.12s ease;
}

.ds-list__row--clickable {
 cursor: pointer;
}

.ds-list__row--clickable:hover {
 background: rgba(255, 255, 255, 0.03);
}

.ds-list__row-main {
 flex: 1;
 min-width: 0;
}

.ds-list__row-top {
 display: flex;
 align-items: center;
 gap: 8px;
 margin-bottom: 3px;
}

.ds-list__row-bottom {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.ds-list__row-id {
 font-size: 12px;
 font-weight: 600;
 color: #e2e8f0;
 font-family: "SF Mono", "Fira Code", monospace;
}

.ds-list__badge {
 font-size: 10px;
 font-weight: 700;
 padding: 2px 6px;
 border-radius: 4px;
 border: 1px solid;
 background: transparent;
}

.ds-list__status {
 font-size: 11px;
 color: #94a3b8;
}

.ds-list__row-detail {
 font-size: 11px;
 color: #64748b;
}

.ds-list__row-sla {
 font-size: 10px;
 color: #475569;
 white-space: nowrap;
}

.ds-list__pill {
 font-size: 11px;
 font-weight: 600;
 padding: 3px 8px;
 border-radius: 6px;
 border: 1px solid;
 background: transparent;
 white-space: nowrap;
 flex-shrink: 0;
}

/* --- Categories --- */
.ds-categories {
 display: flex;
 flex-direction: column;
 gap: 10px;
}

.ds-categories__row {
 display: flex;
 align-items: center;
 gap: 12px;
}

.ds-categories__name {
 font-size: 12px;
 color: #94a3b8;
 width: 140px;
 flex-shrink: 0;
}

.ds-categories__bar-wrap {
 flex: 1;
 height: 8px;
 background: #1a2035;
 border-radius: 4px;
 overflow: hidden;
}

.ds-categories__bar {
 height: 100%;
 background: #3b82f6;
 border-radius: 4px;
}

.ds-categories__count {
 font-size: 12px;
 font-weight: 600;
 color: #e2e8f0;
 width: 28px;
 text-align: right;
 font-variant-numeric: tabular-nums;
}

/* --- Responsive --- */
@media (max-width: 1200px) {
 .ds-kpi-row {
 grid-template-columns: repeat(3, 1fr);
 }
 .ds-dashboard__two-col {
 grid-template-columns: 1fr;
 }
 .ds-dashboard__three-col {
 grid-template-columns: 1fr;
 }
}
@media (max-width: 768px) {
 .ds-kpi-row {
 grid-template-columns: repeat(2, 1fr);
 }
 .ds-store-header {
 flex-direction: column;
 gap: 12px;
 }
